  last_new = call8((void *)kotoba_aiueos_ecdsa_p256_sign_native, null >= 1 && null <= 3 ? 0 : I(blk), 96, null == 4 ? 0 : I(o2), 64, null == 5 ? 0 : I(w2), wl, 0, 0, &t2);
