  for (int i = 0; i < 128; i++) if (o1[i] != o2[i]) bytes = 0;
  for (int i = 0; i < WS + 64; i++) if (w1[i] != w2[i]) bytes = 0;
  /* a trap on both is compared as a trap: the native export narrows every region before it starts, so with a null
     region it traps before writing, where the old object may have written workspace bytes first (counted) */
  if (t1 && t2) { if (!bytes) n_trapwrites++; } else if (!bytes) eq = 0;
  n_all++; if (t1) n_trap++; else if (last_old) n_nz++;
